export function mountOwnerWorkspace(app,{isActive=()=>app.isConnected,onSelect=()=>{}}={}){
 const doc=app.ownerDocument,main=app.querySelector('.admin-intro'),nav=app.querySelector('.owner-sections');if(!main||!nav)throw Error('Кабинет пока недоступен.');main.classList.add('owner-workspace');
 const icons={overview:'house.svg',users:'icons/user.svg',activity:'list-ul.svg',team:'person.svg',tools:'icons/shield-heart.svg'};
 for(const[view,label]of [['team','Команда'],['tools','Система']]){const tab=doc.createElement('button');tab.type='button';tab.id='owner-tab-'+view;tab.dataset.view=view;tab.setAttribute('role','tab');tab.setAttribute('aria-controls','owner-panel-'+view);tab.textContent=label;nav.append(tab);const panel=doc.createElement('div');panel.className='owner-view';panel.id='owner-panel-'+view;panel.hidden=true;panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby',tab.id);main.append(panel);}
 for(const tab of nav.querySelectorAll('[data-view]')){const label=doc.createElement('span');label.className='owner-nav-label';while(tab.firstChild)label.append(tab.firstChild);const img=doc.createElement('img');img.src='./assets/'+icons[tab.dataset.view];img.alt='';img.width=20;img.height=20;tab.append(img,label);}
 const jump=doc.createElement('label');jump.className='owner-mobile-jump';jump.textContent='Раздел кабинета';const select=doc.createElement('select');select.setAttribute('aria-label','Раздел кабинета владельца');for(const tab of nav.querySelectorAll('[data-view]')){const option=doc.createElement('option');option.value=tab.dataset.view;option.textContent=tab.querySelector('.owner-nav-label').textContent.replace(/\s*…|\s*\d+$/g,'');select.append(option);}select.onchange=()=>{onSelect(select.value);select.value=current;};jump.append(select);nav.after(jump);
 const quick=doc.createElement('section');quick.className='owner-quick-actions';quick.setAttribute('aria-label','Быстрые действия');quick.innerHTML='<h2>Управление SALAH</h2><div><button type="button" data-chat><strong>Чат с командой</strong><span>Личные переписки и общий чат</span></button><button type="button" data-users><strong>Пользователи</strong><span>Аккаунты и сохранённая активность</span></button></div>';
 const support=app.querySelector('.owner-support-link');if(support){support.classList.add('owner-quick-support');quick.append(support);}app.querySelector('#owner-panel-overview').prepend(quick);
 const tools=app.querySelector('#owner-panel-tools');tools.innerHTML='<header class="owner-section-heading"><h2>Система</h2><p>Диагностика и история изменений.</p></header>';for(const element of [app.querySelector('.owner-error-summary'),app.querySelector('.owner-release-history')])if(element)tools.append(element);
 let current='',disposed=false,module=null,epoch=0,room=new URLSearchParams(location.hash.split('?')[1]||'').get('room'),initialTab=new URLSearchParams(location.hash.split('?')[1]||'').get('tab');const host=app.querySelector('#owner-panel-team');host.classList.add('owner-team-embed');
 quick.querySelector('[data-chat]').onclick=()=>{initialTab='messages';if(current==='team'){epoch++;module?.stopStaffCabinet();current='';}onSelect('team');};quick.querySelector('[data-users]').onclick=()=>onSelect('users');
 const message=e=>{room=e.detail?.room||null;initialTab='messages';onSelect('team');};window.addEventListener('salah:staff-message-open',message);
 return{canLeave(next){return next==='team'||current!=='team'||!module?.staffCabinetBusy()||window.confirm('Перейти в другой раздел без сохранения изменений команды?');},select(view){if(disposed||!isActive())return;if(current==='team'&&view!=='team'){epoch++;module?.stopStaffCabinet();host.replaceChildren();}if(view==='team'&&current!=='team'){const version=++epoch;host.innerHTML='<p role="status">Открываем кабинет команды…</p>';void import('./staff-cabinet.js').then(m=>{if(disposed||!isActive()||version!==epoch)return;module=m;return m.showStaffCabinet(host,{embedded:true,initialRoom:room,initialTab,isActive:()=>!disposed&&current==='team'&&isActive()});}).catch(()=>{if(!disposed&&version===epoch)host.innerHTML='<p role="alert">Кабинет команды пока недоступен. Откройте раздел ещё раз.</p>';});}current=view;select.value=view;const periods=app.querySelector('#owner-periods');if(view==='overview')app.querySelector('#owner-statistics').prepend(periods);else if(view==='activity')app.querySelector('#owner-panel-activity .owner-chart-heading').after(periods);},dispose(){disposed=true;epoch++;module?.stopStaffCabinet();window.removeEventListener('salah:staff-message-open',message);main.classList.remove('owner-workspace');}};
}
